// lib-error: classify, record, park (N8N-2.5, 6.1).
const item = $input.first().json;
const fromTrigger = item.stage === undefined && item.error_class === undefined
  && item.execution !== undefined && item.workflow !== undefined;
let rec;
if (fromTrigger) {
  const err = item.execution.error ?? {};
  rec = {
    entry: 'error-trigger',
    stage: 'unhandled',
    failing_workflow: item.workflow.name ?? null,
    failing_workflow_id: item.workflow.id ?? null,
    failing_execution_id: item.execution.id ?? null,
    failing_node: item.execution.lastNodeExecuted ?? err.node?.name ?? null,
    wazuh_alert_id: null, // n8n's Error Trigger carries no input data
    thehive_alert_id: null,
    http_status: Number(err.httpCode ?? err.context?.httpCode) || null,
    error_code: err.code ?? err.cause?.code ?? null,
    message: [err.message, err.description].filter(Boolean).join(': ') || 'no message',
    payload: null,
    error_class: null,
  };
} else {
  rec = {
    entry: 'call',
    stage: item.stage ?? null,
    failing_workflow: item.workflow ?? null,
    failing_workflow_id: null,
    failing_execution_id: item.execution_id ?? null,
    failing_sub_execution_id: item.sub_execution_id ?? null,
    failing_node: item.node ?? null,
    wazuh_alert_id: item.wazuh_alert_id ?? null,
    thehive_alert_id: item.thehive_alert_id ?? null,
    http_status: Number(item.http_status) || null,
    error_code: item.error_code ?? null,
    message: item.message ?? null,
    payload: item.payload ?? null,
    error_class: item.error_class ?? null,
  };
}
if (!rec.error_class) {
  const text = `${rec.message ?? ''} ${rec.error_code ?? ''}`;
  const network = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i.test(text);
  const thehive = /thehive/i.test(`${rec.stage ?? ''} ${rec.failing_node ?? ''}`);
  if (thehive && (network || rec.http_status >= 500)) rec.error_class = 'thehive_unreachable';
  else if (thehive && rec.http_status >= 400 && rec.http_status < 500) rec.error_class = 'thehive_4xx';
  else rec.error_class = 'unknown';
}
rec.retryable = rec.error_class === 'thehive_unreachable'; // hint for N8N-6.2/6.3; nothing retries yet
rec.parked_at = new Date().toISOString();
rec.lib_error_execution_id = $execution.id;
return [{ json: rec }];
